import duckdb, os
from pathlib import Path
LAKE=r'D:\repository\数据湖\data\cnequity\duckdb\cnequity.duckdb'
BASE_DIR=Path(r'D:\repository\数据湖\data')
con=duckdb.connect(LAKE,read_only=True)

print('=== 数据湖目录总体积 ===')
total=0
for d in BASE_DIR.rglob('*'):
    if d.is_file():
        total+=d.stat().st_size
print(f'  data/ 目录合计: {total/1024/1024:.1f} MB')
# parquet 各数据集
pq=BASE_DIR/'cnequity'/'parquet'
if pq.exists():
    print('\n=== parquet 各数据集体积 ===')
    rows=[]
    for sub in pq.iterdir():
        if sub.is_dir():
            sz=sum(f.stat().st_size for f in sub.rglob('*.parquet'))
            rows.append((sz, sub.name, len(list(sub.rglob('*.parquet')))))
    for sz,name,nf in sorted(rows,reverse=True):
        print(f'  {sz/1024/1024:8.1f} MB  {name}  ({nf} files)')

# duckdb 主库体积
for f in [LAKE, LAKE+'.wal']:
    if os.path.exists(f): print(f'\n{Path(f).name}: {os.path.getsize(f)/1024/1024:.1f} MB')

print('\n=== 各表行数 / 字段数 ===')
tables=[r[0] for r in con.execute("select table_name from information_schema.tables where table_schema='main' order by 1").fetchall()]
for t in tables:
    try:
        n=con.execute(f'select count(*) from "{t}"').fetchone()[0]
        ncol=len(con.execute(f"select column_name from information_schema.columns where table_name='{t}'").fetchall())
        print(f'  {t:32} rows={n:>9,}  cols={ncol}')
    except Exception as e:
        print(f'  {t}: {str(e)[:50]}')
con.close()

from pathlib import Path
base=Path(r'D:\repository\数据湖\data\cnequity')
def dirsize(p):
    return sum(f.stat().st_size for f in p.rglob('*') if f.is_file())
print('=== data/cnequity 各子树体积 ===')
for sub in sorted(base.iterdir(), key=lambda x:-dirsize(x) if x.is_dir() else 0):
    if sub.is_dir():
        print(f'  {dirsize(sub)/1024/1024:8.1f} MB  {sub.name}/')
    else:
        print(f'  {sub.stat().st_size/1024/1024:8.1f} MB  {sub.name}')

# derived 各数据集
for grp in ['derived','curated','raw','staging','backups']:
    g=base/grp
    if not g.exists(): continue
    print(f'\n=== {grp}/ 各数据集体积 ===')
    items=[]
    for sub in g.iterdir():
        if sub.is_dir(): items.append((dirsize(sub), sub.name+'/'))
        else: items.append((sub.stat().st_size, sub.name))
    for sz,name in sorted(items,reverse=True)[:25]:
        print(f'  {sz/1024/1024:8.2f} MB  {name}')

